      .then((response) => {
        const callbackEndpoint = baseUrl(
          `/api/lastfm/link/callback?state=${encodeURIComponent(
            response.json.state
          )}`
        )
        const callbackUrl = `${window.location.origin}${callbackEndpoint}`
