          `https://www.last.fm/api/auth/?api_key=${
            config.lastFMApiKey
          }&cb=${encodeURIComponent(callbackUrl)}`
        )
      })
      .catch(() => setCheckingLink(false))
  }, [setCheckingLink])

  const endChecking = (success) => {
    linkCheckDelay = null
    setCheckingLink(false)
    if (success) {
      notify('message.lastfmLinkSuccess', 'success')
    } else {
      notify('message.lastfmLinkFailure', 'warning')
    }
    setLinked(success)
  }

  useInterval(() => {
    httpClient('/api/lastfm/link')
      .then((response) => {
        let result = false
        if (response.json.status === true) {
          result = true
